from pathlib import Path
from collections import defaultdict,Counter,deque
R=Path.cwd()
def read(p):
 with (R/p).open(encoding='\\''utf-8-sig'\\'',newline='\\'''\\'') as f:return list(csv.DictReader(f))
M=read('\\''data/Model.csv'\\''); P=read('\\''data/passports_model_list_20260921.csv'\\''); S=read('\\''data/CRISPRScreenMap.csv'\\''); C=read('\\''lock_s/cohort.csv'\\'')
norm=lambda s:re.sub('\\''["'^A-Z0-9]'"'\\'','\\'''\\'',(s or '\\'''\\'').upper())
num=lambda s:str(int(float(s))) if s else '\\'''\\''
I={k:defaultdict(set) for k in ['\\''BROAD_ID'\\'','\\''SIDM'\\'','\\''COSMIC'\\'','\\''HCMI'\\'','\\''NAME'\\'']}
for p in P:
 for route,col,fn in [('\\''BROAD_ID'\\'','\\''BROAD_ID'\\'',str),('\\''SIDM'\\'','\\''model_id'\\'',str),('\\''COSMIC'\\'','\\''COSMIC_ID'\\'',num),('\\''HCMI'\\'','\\''HCMI'\\'',str.strip)]:
  if p[col]:I[route][fn(p[col])].add(p['\\''patient_id'\\''])
 for s in [p['\\''model_name'\\'']]+re.split('\\''[|;]'\\'',p['\\''synonyms'\\'']):
  if norm(s):I['\\''NAME'\\''][norm(s)].add(p['\\''patient_id'\\''])
def res(m):
 d={}
 for route,col,fn in [('\\''BROAD_ID'\\'','\\''ModelID'\\'',str),('\\''SIDM'\\'','\\''SangerModelID'\\'',str),('\\''COSMIC'\\'','\\''COSMICID'\\'',num),('\\''HCMI'\\'','\\''HCMIID'\\'',str.strip)]:
  if m[col] and fn(m[col]) in I[route]:d[route]=I[route][fn(m[col])]
 names=I['\\''NAME'\\''].get(norm(m['\\''CellLineName'\\'']),set())|I['\\''NAME'\\''].get(norm(m['\\''StrippedCellLineName'\\'']),set())
 if names:d['\\''NAME'\\'']=names
 return d
screen_ids={s['\\''ModelID'\\''] for s in S}; screened=[m for m in M if m['\\''ModelID'\\''] in screen_ids]
cr={c['\\''sample_ID'\\'']:sorted(I['\\''NAME'\\''][norm(c['\\''sample_ID'\\''])]) for c in C}
assert all(len(v)==1 for v in cr.values())
cm={k:v[0] for k,v in cr.items()}; cp=set(cm.values())
print('\\''source_counts'\\'',len(M),len(P),len(S),len(C),'\\''Witness'\\'',len(cm),len(cp),'\\''map_sha'\\'',hashlib.sha256(json.dumps(cm,sort_keys=True,separators=('\\'','\\'','\\'':'\\'')).encode()).hexdigest())
print('\\''duplicates'\\'', {label:{k:v for k,v in Counter(r[col] for r in rows).items() if v>1} for label,rows,col in [('\\''ModelID'\\'',M,'\\''ModelID'\\''),('\\''ScreenID'\\'',S,'\\''ScreenID'\\''),('\\''Passports_model_id'\\'',P,'\\''model_id'\\'')]})
print('\\''screen_replicates'\\'',Counter(Counter(s['\\''ModelID'\\''] for s in S).values()),'\\''missing_models'\\'',screen_ids-{m['\\''ModelID'\\''] for m in M},'\\''missing_DM_patient'\\'',sum(not m['\\''PatientID'\\''] for m in M),'\\''missing_PP_patient'\\'',sum(not p['\\''patient_id'\\''] for p in P))
for route in I:
 coll={k:sorted(v) for k,v in I[route].items() if len(v)>1}
 print('\\''index_multi_patient'\\'',route,coll)
RR={m['\\''ModelID'\\'']:res(m) for m in M}
for scope,ms in [('\\''all'\\'',M),('\\''screened'\\'',screened)]:
 print(scope,'\\''resolution_cardinality'\\'',Counter(len(set().union(*RR[m['\\''ModelID'\\'']].values())) for m in ms))
 for m in ms:
  pats=set().union(*RR[m['\\''ModelID'\\'']].values())
  if len(pats)>1 or (RR[m['\\''ModelID'\\'']] and not ({'\\''BROAD_ID'\\'','\\''SIDM'\\'','\\''HCMI'\\''}&RR[m['\\''ModelID'\\'']].keys())):
   print(scope,'\\''interesting'\\'',json.dumps({k:m[k] for k in ['\\''ModelID'\\'','\\''PatientID'\\'','\\''CellLineName'\\'','\\''SangerModelID'\\'','\\''COSMICID'\\'','\\''HCMIID'\\'']}),{k:sorted(v) for k,v in RR[m['\\''ModelID'\\'']].items()})
for scope,ms in [('\\''screened'\\'',screened),('\\''all'\\'',M)]:
 g=defaultdict(set)
 for m in ms:
  a=('\\''DM'\\'',m['\\''PatientID'\\'']);g[a]
  for p in set().union(*RR[m['\\''ModelID'\\'']].values()):b=('\\''PP'\\'',p);g[a].add(b);g[b].add(a)
 reach={('\\''PP'\\'',p) for p in cp};q=deque(reach)
 while q:
  for x in g[q.popleft()]-reach:reach.add(x);q.append(x)
 groups={};i=0
 for x in list(g):
  if x in groups:continue
  i+=1;groups[x]=i;q=deque([x])
  while q:
   for y in g[q.popleft()]:
    if y not in groups:groups[y]=i;q.append(y)
 classes=defaultdict(list)
 for m in screened:
  ps=set().union(*RR[m['\\''ModelID'\\'']].values())
  classes['\\''unresolved'\\'' if not ps else '\\''overlap'\\'' if ('\\''DM'\\'',m['\\''PatientID'\\'']) in reach else '\\''established'\\''].append(m)
 for k,ms2 in classes.items():
  print(scope,k,{'\\''models'\\'':len(ms2),'\\''DM'\\'':len({m['\\''PatientID'\\''] for m in ms2}),'\\''PP'\\'':len(set().union(*(set().union(*RR[m['\\''ModelID'\\'']].values()) for m in ms2))),'\\''components'\\'':len({groups['\\''DM'\\'',m['\\''PatientID'\\'']] for m in ms2}),'\\''organoids'\\'':sum(m['\\''ModelType'\\'']=='\\''Organoid'\\'' for m in ms2)})
 if scope=='\\''screened'\\'':
  stored=json.loads((R/'\\''generations/sgen010/established_pool_v1.json'\\'').read_text())
  for k,key in [('\\''established'\\'','\\''established_model_ids'\\''),('\\''unresolved'\\'','\\''unresolved_model_ids'\\''),('\\''overlap'\\'','\\''c_overlap_model_ids'\\'')]:assert {m['\\''ModelID'\\''] for m in classes[k]}==set(stored[key]),k
  for mid,rs in stored['\\''resolution'\\''].items():assert set(rs['\\''patients_SIDP'\\''])==set().union(*RR[mid].values()) and set(rs['\\''routes'\\''])==set(RR[mid]),mid
print('\\''independent graph and resolution match stored pool'\\'')
ns=runpy.run_path(str(R/'\\''src/sgen010_screen_v4.py'\\''))
class Output:
 def __init__(self):self.buffer=None
 def open(self,mode):
  assert mode=='\\''x'\\'';self.buffer=io.StringIO();return contextlib.nullcontext(self.buffer)
a=Output();b=Output();ns['\\''main'\\''].__globals__.update(OUT=a,POOL_OUT=b)
with contextlib.redirect_stdout(io.StringIO()) as out:rc=ns['\\''main'\\'']()
print('\\''script_rc'\\'',rc,'\\''report_match'\\'',json.loads(a.buffer.getvalue())==json.loads((R/'\\''generations/sgen010/screen_v4.json'\\'').read_text()),'\\''pool_match'\\'',json.loads(b.buffer.getvalue())==stored)
print('\\''clinical_populated'\\'',[(col,sum(bool(r.get(col)) for r in rows)) for rows,col in [(M,'\\''PatientTreatmentResponse'\\''),(P,'\\''prior_therapy_outcome'\\''),(P,'\\''tumour_regression_score'\\'')]])
print('\\''PP_clinical_retained'\\'',[(k,sum(bool(r[k]) for r in ns['\\''rows'\\''](R/'\\''data/passports_model_list_20260921.csv'\\''))) for k in ['\\''prior_therapy_outcome'\\'','\\''tumour_regression_score'\\'']])
'"

